 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    paths = []

    # Each marker extends along its color's fixed vector. Intermediate cells
    # are 5; the endpoint repeats the marker color. Crossings are 4.
    moves = {1: (-1, 2), 2: (0, -4), 3: (3, 0), 6: (-6, 0)}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in moves:
                continue
            dr, dc = moves[color]
            steps = max(abs(dr), abs(dc))
            # Color 1's two-step move follows a horizontal-then-vertical
            # elbow: two cells right, then one cell up to its endpoint.
            cells = []
            if color == 1:
                cells.extend([(r, c + 1), (r, c + 2)])
                cells.append((r - 1, c + 2))
            else:
                for k in range(1, steps + 1):
                    cells.append((r + dr * k // steps, c + dc * k // steps))
            valid = [(rr, cc) for rr, cc in cells if 0 <= rr < h and 0 <= cc < w]
            for rr, cc in valid[:-1]:
                paths.append((rr, cc))
                out[rr][cc] = 5
            if valid:
                rr, cc = valid[-1]
                paths.append((rr, cc))
                out[rr][cc] = color

    counts = {}
    for cell in paths:
        counts[cell] = counts.get(cell, 0) + 1
    for (r, c), n in counts.items():
        if n > 1:
            out[r][c] = 4
    return out
